package remote

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6/plumbing"
)

// WriteProbeFetchBudget bounds the on-demand ref fetch performed by a
// BACKFILL's absence probe. Write paths run inside git hooks (post-commit,
// stop-time finalize) where a dead network must not stall the user's
// workflow for the read path's full fetch window; combined with the
// per-store failure memo in the git-refs store, a loop over N checkpoints
// pays a dead network once, briefly.
const WriteProbeFetchBudget = 15 * time.Second

// readFetchTimeout bounds the interactive read-path fetch (unchanged from
// the historical FetchCheckpointRef behavior).
const readFetchTimeout = 2 * time.Minute

// CheckpointFetchTarget returns the git remote (URL or name) that checkpoint
// data is fetched from. It prefers the effective URL resolved by FetchURL,
// which is the source of truth for checkpoint fetch location. If URL
// resolution fails, it falls back to the origin remote name so callers can
// still attempt a fetch.
func CheckpointFetchTarget(ctx context.Context) string {
	target, _ := checkpointFetchTarget(ctx)
	return target
}

// checkpointFetchTarget is CheckpointFetchTarget plus whether the target is
// authoritative for checkpoint refs (see fetchURLAuthoritative). A resolved
// origin is also non-authoritative when checkpoint_push_remote elects another
// remote: it may still be probed as a fallback, but cannot certify absence.
func checkpointFetchTarget(ctx context.Context) (string, bool) {
	target, authoritative := checkpointFetchTargetFrom(ctx, "")
	if !authoritative {
		return target, false
	}

	s, err := settings.Load(ctx)
	if err != nil {
		return target, false
	}
	if s.HasCheckpointRemoteKey() {
		return target, s.GetCheckpointRemote() != nil
	}

	pushRemote := s.GetCheckpointPushRemote()
	return target, pushRemote == "" || pushRemote == originRemote
}

func checkpointFetchTargetFrom(ctx context.Context, leadRemote string) (string, bool) {
	url, authoritative, err := fetchURLAuthoritative(ctx, FetchURLOptions{LeadReadRemote: leadRemote})
	if err == nil && url != "" {
		return url, authoritative
	}
	if leadRemote != "" {
		return leadRemote, false
	}
	return "origin", false
}

// FetchCheckpointRef fetches a single per-checkpoint ref
// (refs/entire/checkpoints/<shard>/<id>) from the checkpoint remote into the
// local ref of the same name, so the git-refs store can resolve a checkpoint
// written on another machine.
//
// Contract — absence is distinguishable from failure:
//   - The remote genuinely lacking the ref returns an error wrapping
//     plumbing.ErrReferenceNotFound (probed via ls-remote before fetching,
//     because `git fetch` of a missing refspec fails indistinguishably from a
//     transport error). Store probes classify this as "checkpoint not found",
//     which write routing may legitimately act on.
//   - Any transport-level failure (probe or fetch) is surfaced as a real
//     error, never mapped to absence — a false "absent" would misdirect a
//     backfill onto another backend instead of retrying.
//   - A repository with no git remotes at all and no checkpoint_remote
//     configured also returns an error wrapping plumbing.ErrReferenceNotFound
//     without probing: there is no remote that could host the ref.
func FetchCheckpointRef(ctx context.Context, ref plumbing.ReferenceName) error {
	ctx, cancel := context.WithTimeout(ctx, readFetchTimeout)
	defer cancel()

	fetchTarget, authoritative := checkpointFetchTarget(ctx)

	// A fully local repository — no git remotes at all and no
	// checkpoint_remote configured — has no remote that could host checkpoint
	// refs, so the ref's local absence is the final verdict. Without this,
	// the origin-name fallback below probes a remote git cannot resolve
	// ("'origin' does not appear to be a git repository", exit 128) and a
	// remoteless repo is misreported as a transport outage. Absence is only
	// ever classified on positive evidence; each escape below keeps today's
	// hard-failure probe:
	//   - dead caller context: every subprocess fails for reasons that say
	//     nothing about the repository
	//   - unreadable settings: a configured checkpoint remote cannot be
	//     ruled out
	//   - checkpoint_remote key present in any form, valid or malformed
	//     (see settings.HasCheckpointRemoteKey for why key presence, not
	//     GetCheckpointRemote, is the signal)
	//   - any remote listed, or the listing itself failing: checkpoint refs
	//     are pushed to whatever remote the pre-push hook fires for, so a
	//     repo with only non-origin remotes is NOT remoteless
	// The skipped-guard cases surface through the ordinary probe paths: a
	// missing origin fails the ls-remote probe as a transport error, and an
	// origin that merely lacks the ref hits the fallback-emptiness refusal
	// below — neither classifies as absence.
	if fetchTarget == originRemote && !authoritative && ctx.Err() == nil {
		s, loadErr := settings.Load(ctx)
		switch {
		case loadErr != nil:
			logging.Warn(ctx, "checkpoint probe: settings unreadable; cannot rule out a configured checkpoint remote, probing anyway",
				slog.String("error", loadErr.Error()))
		case !s.HasCheckpointRemoteKey() && repoHasNoRemotes(ctx):
			logging.Debug(ctx, "checkpoint probe: repository has no git remotes; classifying ref as absent",
				slog.String("ref", ref.String()))
			return fmt.Errorf("checkpoint ref %s: repository has no git remotes to fetch from: %w", ref, plumbing.ErrReferenceNotFound)
		}
	}

	return probeAndFetchCheckpointRef(ctx, ref, fetchTarget, authoritative)
}

// FetchCheckpointRefFrom fetches a checkpoint ref from an ordered read chain.
// Candidates advance only after positive absence. A transport failure stops
// the chain because hydrating a legacy ref into the canonical local ref while
// the elected remote is unavailable could make stale data shadow the elected
// copy. A configured checkpoint_remote keeps the existing single-target
// behavior.
func FetchCheckpointRefFrom(ctx context.Context, ref plumbing.ReferenceName, readRemotes []string) error {
	s, loadErr := settings.Load(ctx)
	if loadErr != nil || s.HasCheckpointRemoteKey() {
		return FetchCheckpointRef(ctx, ref)
	}

	if len(readRemotes) == 0 {
		probeCtx, cancel := context.WithTimeout(ctx, readFetchTimeout)
		defer cancel()
		if probeCtx.Err() == nil && !s.HasCheckpointRemoteKey() && repoHasNoRemotes(probeCtx) {
			logging.Debug(probeCtx, "checkpoint probe: repository has no git remotes; classifying ref as absent",
				slog.String("ref", ref.String()))
			return fmt.Errorf("checkpoint ref %s: repository has no git remotes to fetch from: %w", ref, plumbing.ErrReferenceNotFound)
		}
		return fmt.Errorf("checkpoint ref %s: no checkpoint read candidates available and the repository is not provably remoteless; refusing to treat this as absence", ref)
	}

	var firstErr error
	for i, remoteName := range readRemotes {
		candidateCtx, cancel := context.WithTimeout(ctx, readFetchTimeout)
		target, authoritative := checkpointFetchTargetFrom(candidateCtx, remoteName)
		var err error
		if !authoritative {
			err = fmt.Errorf("resolve checkpoint read candidate %q: resolved target %s is not authoritative", remoteName, RedactURL(target))
		} else {
			err = probeAndFetchCheckpointRef(candidateCtx, ref, target, true)
		}
		cancel()
		if err == nil {
			return nil
		}
		if firstErr == nil {
			firstErr = err
		}
		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
			return err
		}
		if i+1 < len(readRemotes) {
			logging.Debug(ctx, "checkpoint ref fetch: read candidate failed; trying next candidate",
				slog.String("ref", ref.String()),
				slog.String("candidate", remoteName),
				slog.String("error", err.Error()))
		}
	}
	return firstErr
}

func probeAndFetchCheckpointRef(ctx context.Context, ref plumbing.ReferenceName, fetchTarget string, authoritative bool) error {
	out, err := LsRemoteInDir(ctx, "", fetchTarget, ref.String())
	if err != nil {
		// Redact: fetchTarget can be a remote URL with embedded credentials
		// (CI origin URLs), and this error is logged and shown to users.
		return fmt.Errorf("probe checkpoint ref %s on %s: %w", ref, RedactURL(fetchTarget), err)
	}
	if len(bytes.TrimSpace(out)) == 0 {
		if !authoritative {
			// The probe hit an origin FALLBACK while a checkpoint_remote is
			// configured (or undeterminable) — a remote that may simply never
			// host the configured checkpoint refs. Emptiness there proves
			// nothing; classifying it as absence would silently drop backfills
			// for checkpoints that exist on the real checkpoint remote.
			return fmt.Errorf("checkpoint ref %s not visible on fallback remote %s, and the configured checkpoint remote could not be resolved; refusing to treat this as absence", ref, RedactURL(fetchTarget))
		}
		return fmt.Errorf("checkpoint ref %s not found on %s: %w", ref, RedactURL(fetchTarget), plumbing.ErrReferenceNotFound)
	}

	refSpec := "+" + ref.String() + ":" + ref.String()
	if fetchOut, err := Fetch(ctx, FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
	}); err != nil {
		// Fold git's own output into the error (redacted): a bare
		// "exit status 128" is undebuggable in hook Warn logs.
		msg := strings.TrimSpace(string(fetchOut))
		msg = strings.ReplaceAll(msg, fetchTarget, RedactURL(fetchTarget))
		if msg != "" {
			return fmt.Errorf("fetch checkpoint ref %s from %s: %s: %w", ref, RedactURL(fetchTarget), msg, err)
		}
		return fmt.Errorf("fetch checkpoint ref %s from %s: %w", ref, RedactURL(fetchTarget), err)
	}
	return nil
}

// repoHasNoRemotes reports whether the repository at the current directory
// definitively has no git remotes configured. Only a successful, empty
// `git remote` listing counts as proof; any error (dead context, missing git
// binary, not a repository) returns false so the caller falls through to the
// probe instead of classifying absence off an undifferentiated failure.
func repoHasNoRemotes(ctx context.Context) bool {
	out, err := exec.CommandContext(ctx, "git", "remote").Output()
	return err == nil && len(bytes.TrimSpace(out)) == 0
}

// HookCheckpointRefFetcher returns the write-probe fetcher for git-hook
// contexts (post-commit attribution, stop-time transcript finalize): the
// bounded budget plus BatchMode SSH, so a passphrase-protected key can never
// prompt — or invisibly hang — inside a hook the user's git command is
// waiting on.
//
// This remains single-target because write-side probes must not broaden their
// destination beyond the remote selected by the push flow.
func HookCheckpointRefFetcher() func(context.Context, plumbing.ReferenceName) error {
	bounded := BoundedCheckpointRefFetcher(WriteProbeFetchBudget)
	return func(ctx context.Context, ref plumbing.ReferenceName) error {
		return bounded(WithNonInteractiveSSH(ctx), ref)
	}
}

// BoundedCheckpointRefFetcher returns a RefFetchFunc-shaped fetcher whose
// per-call budget is capped at d, for wiring into write-path checkpoint
// stores (see WriteProbeFetchBudget).
func BoundedCheckpointRefFetcher(d time.Duration) func(context.Context, plumbing.ReferenceName) error {
	return func(ctx context.Context, ref plumbing.ReferenceName) error {
		ctx, cancel := context.WithTimeout(ctx, d)
		defer cancel()
		return FetchCheckpointRef(ctx, ref)
	}
}

package remote

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6"
)

const originRemote = "origin"

const (
	ProtocolSSH    = gitremote.ProtocolSSH
	ProtocolHTTPS  = gitremote.ProtocolHTTPS
	ProtocolEntire = gitremote.ProtocolEntire
)

// Info is an alias for gitremote.Info.
type Info = gitremote.Info

// FetchURLOptions configures FetchURL.
type FetchURLOptions struct {
	WorktreeRoot string

	// LeadReadRemote is the checkpoint read candidate the caller wants the
	// fetch URL derived from (the elected sync remote, or one entry of the
	// read-candidate chain while iterating it), supplied by cli/strategy
	// callers — this package cannot resolve the election itself. When set and
	// NO checkpoint_remote is configured, the base fetch URL is derived from
	// it instead of unconditionally from origin. The dedicated
	// checkpoint_remote derivation path ignores it entirely.
	LeadReadRemote string
}

// FetchURL returns the effective checkpoint fetch URL for the current repository.
// If strategy_options.checkpoint_remote is configured, the returned URL is derived
// from the origin remote's protocol/host and the configured checkpoint repo.
// Otherwise, the origin remote URL is returned directly.
//
// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
// forced so the token can be used even when origin is configured via SSH.
func FetchURL(ctx context.Context, opts ...FetchURLOptions) (string, error) {
	url, _, err := fetchURLAuthoritative(ctx, opts...)
	return url, err
}

// fetchURLAuthoritative is FetchURL plus whether the returned URL is
// authoritative for checkpoint refs. It is false exactly when a
// checkpoint_remote IS configured (or cannot be determined) but resolution
// fell back to the origin URL — a remote that by construction does not host
// the configured checkpoint refs. Callers that classify "ref absent on the
// remote" (FetchCheckpointRef's ls-remote probe) must not treat emptiness on
// a non-authoritative target as absence.
func fetchURLAuthoritative(ctx context.Context, opts ...FetchURLOptions) (string, bool, error) {
	var opt FetchURLOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	getRemoteURL := GetRemoteURL
	if opt.WorktreeRoot != "" {
		ctx = settings.WithWorktreeRoot(ctx, opt.WorktreeRoot)
		getRemoteURL = func(ctx context.Context, remoteName string) (string, error) {
			return GetRemoteURLInDir(ctx, opt.WorktreeRoot, remoteName)
		}
	}

	withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""

	originURL, originErr := getRemoteURL(ctx, originRemote)
	if originErr != nil {
		originURL = ""
	}

	if originURL != "" && withToken {
		if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
			originURL = tokenURL
		}
	}

	s, err := settings.Load(ctx)
	if err != nil {
		if originURL != "" {
			logFallback(ctx, "fetch", originURL, "load settings", err)
			// Settings unreadable → checkpoint_remote unknown; conservative:
			// do not certify origin as authoritative for checkpoint refs.
			return originURL, false, nil
		}
		return "", false, fmt.Errorf("load settings: %w", err)
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		// No checkpoint_remote configured: the caller-supplied read candidate
		// (the elected checkpoint sync remote, or the chain entry being
		// tried) is the checkpoint host; without one, origin is.
		if lead := opt.LeadReadRemote; lead != "" && lead != originRemote {
			leadURL, leadErr := getRemoteURL(ctx, lead)
			if leadErr == nil && leadURL == "" {
				leadErr = fmt.Errorf("remote %q has an empty URL", lead)
			}
			if leadErr == nil {
				if withToken {
					if tokenURL, ok := deriveTokenOriginURL(leadURL); ok {
						leadURL = tokenURL
					}
				}
				return leadURL, true, nil
			}
			if originURL != "" {
				// The lead candidate's URL could not be resolved; fall back to
				// origin but do not certify it as the checkpoint host.
				logFallback(ctx, "fetch", originURL, "resolve read candidate remote URL", leadErr,
					slog.String("read_candidate", lead))
				return originURL, false, nil
			}
			return "", false, fmt.Errorf("no fetch URL found for read candidate %q: %w", lead, leadErr)
		}
		if originURL == "" {
			return "", false, fmt.Errorf("no fetch URL found: %w", originErr)
		}
		return originURL, true, nil
	}

	if withToken {
		host, ok := providerHost(config.Provider)
		if ok {
			checkpointURL, err := deriveCheckpointURLFromInfo(&Info{
				Protocol: ProtocolHTTPS,
				Host:     host,
			}, config)
			if err == nil {
				return checkpointURL, true, nil
			}
		}

		// In token-based execution path, short-circuit to avoid additional
		// change in protocol.
		if originURL != "" {
			return originURL, false, nil
		}
	}

	if originURL == "" {
		return "", false, fmt.Errorf("no fetch URL found: %w", originErr)
	}

	info, err := ParseURL(originURL)
	if err != nil {
		logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
		return originURL, false, nil
	}

	checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
	if err != nil {
		// Origin's protocol can't be mapped to a checkpoint URL (e.g. file://,
		// or an entire:// mirror of a different forge than the configured
		// provider). Honor the configured checkpoint_remote by targeting the
		// provider's canonical host over HTTPS rather than falling back to origin.
		if providerURL, ok := resolveProviderCheckpointURL(ctx, config, opt.WorktreeRoot); ok {
			return providerURL, true, nil
		}
		logFallback(ctx, "fetch", originURL, "derive checkpoint remote URL", err)
		return originURL, false, nil
	}

	return checkpointURL, true, nil
}

// PushURL returns the effective checkpoint push URL for the current repository.
// Unlike FetchURL:
//   - it derives protocol from the requested push remote, not always origin
//   - it skips checkpoint remote use when the push remote owner differs
//     from the configured checkpoint remote owner
//
// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
// even when the push remote is configured via SSH.
//
// The boolean return value reports whether a dedicated checkpoint_remote is
// configured and should be used for push. When false, the returned URL is the
// repository's origin URL as a fallback.
func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
	originURL := ""
	if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
		originURL = resolvedOriginURL
	}

	s, err := settings.Load(ctx)
	if err != nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "load settings", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", false, fmt.Errorf("load settings: %w", err)
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr != nil {
			return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
		}
		return fallbackURL, false, nil
	}

	pushRemoteURL, err := GetPushURL(ctx, pushRemoteName)
	if err != nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}

	// Whether to use the checkpoint remote at all is a question about THIS repo
	// ("is this checkpoint_remote mine, or did I inherit it by forking?"), not
	// about where the current push happens to be headed — origin decides. The
	// push remote is passed only as the fallback identity for a repo that has no
	// origin at all; see checkpointRemoteIsInherited.
	if inherited, reason := checkpointRemoteIsInherited(ctx, config, originURL, pushRemoteURL); inherited {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr != nil {
			return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
		}
		logging.Warn(ctx, "checkpoint-remote: ignoring checkpoint_remote that appears to belong to another owner; pushing checkpoints to the push remote instead",
			slog.String("checkpoint_repo", config.Repo),
			slog.String("reason", reason),
			slog.String("hint", "if this checkpoint repo is yours, configure checkpoint_remote in .entire/settings.local.json"),
		)
		return fallbackURL, false, nil
	}

	pushInfo, err := ParseURL(pushRemoteURL)
	if err != nil {
		if originURL != "" {
			logFallback(ctx, "push", originURL, "parse push remote URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return originURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}
	withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
	if withToken && isDirectGitTransport(pushInfo.Protocol) {
		// Coerce a direct (ssh/https) remote to HTTPS so the token applies,
		// keeping the host so enterprise installations stay on their own host.
		// An entire:// remote carries a cluster host that isn't a usable HTTPS
		// host, so it's handled separately after the owner check below.
		//
		// Keep the port only when the source was already HTTPS. SSH ports
		// (e.g., :2222) don't map to HTTPS ports on the same host.
		port := ""
		if pushInfo.Protocol == ProtocolHTTPS {
			port = pushInfo.Port
		}
		pushInfo = &Info{
			Protocol: ProtocolHTTPS,
			Host:     pushInfo.Host,
			Port:     port,
			Owner:    pushInfo.Owner,
			Repo:     pushInfo.Repo,
		}
	}

	if withToken && pushInfo.Protocol == ProtocolEntire {
		// The checkpoint token is an HTTPS credential for the provider host;
		// it can't ride through the entire:// helper (which does its own
		// auth). Route to the provider over HTTPS instead of the mirror.
		if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
			return providerURL, true, nil
		}
	}

	pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
	if err != nil {
		// The push remote's protocol can't be mapped to a checkpoint URL
		// (e.g. file://, or an entire:// mirror of a different forge than the
		// configured provider). Honor the configured checkpoint_remote by
		// targeting the provider's canonical host over HTTPS rather than
		// misrouting checkpoints to the origin remote.
		if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
			return providerURL, true, nil
		}
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}

	return pushURL, true, nil
}

// Configured reports whether a structured checkpoint_remote is configured.
func Configured(ctx context.Context) bool {
	s, err := settings.Load(ctx)
	if err != nil {
		logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
			slog.String("error", err.Error()),
		)
		return false
	}
	return s.GetCheckpointRemote() != nil
}

// GetRemoteURL returns the URL configured for the named git remote.
func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
	url, err := gitremote.GetRemoteURL(ctx, remoteName)
	if err != nil {
		return "", fmt.Errorf("get remote URL: %w", err)
	}
	return url, nil
}

// GetPushURLs returns every URL a push to remoteName delivers to, in the order
// git will use them. See gitremote.GetPushURLs for why this differs from
// GetRemoteURL.
func GetPushURLs(ctx context.Context, remoteName string) ([]string, error) {
	urls, err := gitremote.GetPushURLs(ctx, remoteName)
	if err != nil {
		return nil, fmt.Errorf("get push URLs: %w", err)
	}
	return urls, nil
}

// GetPushURL returns the URL a push to remoteName delivers to. A remote's push
// destination is remote.<name>.pushurl when set and only otherwise its url, so
// reading the plain url (as GetRemoteURL does) can name a different repository
// than the one being pushed to.
//
// When several push URLs are configured this returns the FIRST, which is not an
// arbitrary pick: resolveRefsPushDestination sends checkpoint refs to exactly
// that URL, so the URL this derives transport and (origin-less) ownership from
// is the URL the checkpoints land in.
func GetPushURL(ctx context.Context, remoteName string) (string, error) {
	urls, err := GetPushURLs(ctx, remoteName)
	if err != nil {
		return "", err
	}
	return urls[0], nil
}

// checkpointRemoteIsInherited reports whether the configured checkpoint_remote
// looks like it belongs to an upstream project rather than to this developer,
// along with a short reason for logging.
//
// checkpoint_remote is normally committed in .entire/settings.json, so anyone who
// forks or clones the project inherits it. Honoring it blindly would push a
// contributor's session data into the upstream project's checkpoint repo — which
// they typically cannot write to and should not be writing to. This is the check
// that guards against that (added in e8b589835 as "fork detection").
//
// Ownership is decided from two local signals, no network:
//
//  1. A checkpoint_remote in .entire/settings.local.json is gitignored and
//     per-clone, so it cannot have been inherited — it is always ours.
//  2. Otherwise, compare the CHECKPOINT repo's owner against ORIGIN's owner:
//     "am I working in a repo owned by whoever owns the checkpoint repo?" A fork
//     clone has origin <fork>/app against a checkpoint repo owned by upstream,
//     and so mismatches.
//
// Deliberately NOT keyed on the push remote. The predecessor compared the push
// destination's owner, which conflates "is this setting mine" with "where is this
// particular push going": pushing to any differently-owned remote (a backup, a
// colleague's fork) disabled the user's own checkpoint_remote and sent the
// checkpoints to that remote instead. It also has no single answer for a remote
// carrying several push URLs with different owners, where one boolean has to
// cover the whole set — still the case on the git-branch backend, which fans out
// to every push URL.
//
// An origin whose owner cannot be determined (no origin remote, or a non-forge
// URL such as a bare local path) counts as inherited: for a committed setting we
// cannot confirm ownership, and falling back preserves the previous behavior for
// those repos. settings.local.json is the escape hatch when the checkpoint repo
// is genuinely ours but owned by a different account or org than origin.
func checkpointRemoteIsInherited(ctx context.Context, config *settings.CheckpointRemoteConfig, originURL, pushRemoteURL string) (bool, string) {
	checkpointOwner := config.Owner()
	if checkpointOwner == "" {
		// No owner to compare (malformed repo field). Matches the predecessor,
		// which skipped the check rather than blocking on it.
		return false, ""
	}
	if settings.CheckpointRemoteIsLocalOnly(ctx) {
		return false, ""
	}

	// Origin identifies the repo we are working in. Without one, the push remote
	// is the only identity available, and using it is what the predecessor
	// effectively did — a repo whose only remote is e.g. "upstream" must not lose
	// its configured checkpoint remote just because nothing is named "origin".
	// There is no origin-vs-push-remote divergence to worry about in that case:
	// the repo has exactly one identity.
	identityURL, identitySource := originURL, "origin"
	if identityURL == "" {
		identityURL, identitySource = pushRemoteURL, "push remote"
	}
	if identityURL == "" {
		return true, "no remote to establish ownership"
	}

	info, err := ParseURL(identityURL)
	if err != nil || info.Owner == "" {
		return true, identitySource + " URL owner could not be determined"
	}
	if strings.EqualFold(info.Owner, checkpointOwner) {
		return false, ""
	}
	return true, fmt.Sprintf("%s owner %q differs from checkpoint owner %q", identitySource, info.Owner, checkpointOwner)
}

// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
	url, err := gitremote.GetRemoteURLInDir(ctx, dir, remoteName)
	if err != nil {
		return "", fmt.Errorf("get remote URL: %w", err)
	}
	return url, nil
}

// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
func ParseURL(rawURL string) (*Info, error) {
	info, err := gitremote.ParseURL(rawURL)
	if err != nil {
		return nil, fmt.Errorf("parse URL: %w", err)
	}
	return info, nil
}

// isDirectGitTransport reports whether the protocol talks to the git host
// directly over ssh/https (where the host is a usable HTTPS host for token
// auth), as opposed to a remote helper scheme like entire:// or a local
// file://.
func isDirectGitTransport(protocol string) bool {
	return protocol == ProtocolSSH || protocol == ProtocolHTTPS
}

func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
	switch info.Protocol {
	case ProtocolSSH:
		// SCP-style (git@host:repo) doesn't support ports. When a non-default
		// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
		if info.Port != "" {
			return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
		}
		return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
	case ProtocolHTTPS:
		return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
	case ProtocolEntire:
		// entire:// push-through mirrors are cluster-scoped: keep the cluster
		// host and forge segment, swap in the checkpoint repo. Only derivable
		// when the forge maps back to the configured provider's host, so a
		// github checkpoint_remote never routes through another forge's mirror.
		host, ok := providerHost(config.Provider)
		if !ok || !strings.EqualFold(info.CanonicalHost(), host) {
			return "", fmt.Errorf("entire:// remote forge %q does not match checkpoint provider %q", info.Forge, config.Provider)
		}
		return fmt.Sprintf("entire://%s/%s/%s", info.HostPort(), info.Forge, config.Repo), nil
	default:
		return "", fmt.Errorf("unsupported protocol %q in remote URL", info.Protocol)
	}
}

// resolveProviderCheckpointURL builds the checkpoint URL for the configured
// provider, choosing the transport from what's already configured for that
// endpoint. It is the fallback used when the push/origin remote's protocol can't
// be mapped to a git transport (e.g. entire://, file://): the configured
// checkpoint_remote names a concrete provider, so checkpoints go there rather
// than being misrouted to the origin remote.
//
// Transport precedence:
//  1. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS on the provider host (the token is
//     the credential).
//  2. An existing remote already targets the provider host -> reuse its scheme,
//     so checkpoints use the same auth the user already has for that endpoint.
//  3. Otherwise SSH on the provider host.
//
// Returns ok=false when no transport can be determined (unknown provider with no
// usable signal), in which case the caller falls back to the origin remote.
func resolveProviderCheckpointURL(ctx context.Context, config *settings.CheckpointRemoteConfig, dir string) (string, bool) {
	repo, err := openRepoAt(ctx, dir)
	if err != nil {
		repo = nil // Fall back to env/provider-only signals.
	}

	info, ok := pickProviderTransport(repo, config)
	if !ok {
		return "", false
	}
	url, err := deriveCheckpointURLFromInfo(info, config)
	if err != nil {
		return "", false
	}
	return url, true
}

// pickProviderTransport returns the protocol/host/port to use when deriving a
// checkpoint URL, following the precedence documented on
// resolveProviderCheckpointURL.
func pickProviderTransport(repo *git.Repository, config *settings.CheckpointRemoteConfig) (*Info, bool) {
	host, hostOK := providerHost(config.Provider)

	// 1. Explicit token -> HTTPS on the provider host.
	if hostOK && strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
		return &Info{Protocol: ProtocolHTTPS, Host: host}, true
	}

	// 2. An existing remote already targeting the provider host -> reuse scheme.
	if hostOK && repo != nil {
		if info, ok := findRemoteInfoForHost(repo, host); ok {
			return &Info{Protocol: info.Protocol, Host: info.Host, Port: info.Port}, true
		}
	}

	// 3. Default to SSH on the provider host.
	if hostOK {
		return &Info{Protocol: ProtocolSSH, Host: host}, true
	}

	return nil, false
}

// openRepoAt opens the git repository at dir (current directory when dir is
// empty). It routes through gitrepo, the single reftable-aware opener, so a
// reftable repository is opened via the git-CLI storer rather than rejected by
// go-git's extension check. gitrepo.OpenCurrent resolves the worktree root from
// the current directory (the walk-up equivalent of the previous DetectDotGit
// open) when no explicit root is given.
func openRepoAt(ctx context.Context, dir string) (*git.Repository, error) {
	if dir == "" {
		repo, err := gitrepo.OpenCurrent(ctx)
		if err != nil {
			return nil, fmt.Errorf("open git repository: %w", err)
		}
		return repo, nil
	}
	repo, err := gitrepo.OpenPath(dir)
	if err != nil {
		return nil, fmt.Errorf("open git repository: %w", err)
	}
	return repo, nil
}

// findRemoteInfoForHost returns the parsed Info of the first configured git
// remote (in deterministic name order) whose host matches host and whose
// protocol is a usable git transport (ssh/https). entire:// and other
// non-transport remotes are ignored.
func findRemoteInfoForHost(repo *git.Repository, host string) (*Info, bool) {
	cfg, err := repo.Config()
	if err != nil {
		return nil, false
	}
	names := make([]string, 0, len(cfg.Remotes))
	for name := range cfg.Remotes {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		for _, rawURL := range cfg.Remotes[name].URLs {
			info, err := gitremote.ParseURL(rawURL)
			if err != nil {
				continue
			}
			if strings.EqualFold(info.Host, host) && isDirectGitTransport(info.Protocol) {
				return info, true
			}
		}
	}
	return nil, false
}

func deriveTokenOriginURL(originURL string) (string, bool) {
	info, err := gitremote.ParseURL(originURL)
	if err != nil {
		return "", false
	}
	if info.Host == "" || info.Owner == "" || info.Repo == "" {
		return "", false
	}
	// Keep the port only when the source was already HTTPS. SSH ports
	// (e.g., :2222) don't map to HTTPS ports on the same host.
	hostPort := info.Host
	if info.Protocol == ProtocolHTTPS {
		hostPort = info.HostPort()
	}
	return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
}

func providerHost(provider string) (string, bool) {
	switch strings.ToLower(strings.TrimSpace(provider)) {
	case "github":
		return "github.com", true
	case "gitlab":
		return "gitlab.com", true
	default:
		return "", false
	}
}

// RedactURL removes credentials and query parameters from a URL for safe logging.
func RedactURL(rawURL string) string {
	return gitremote.RedactURL(rawURL)
}

// RedactURLOrPath is RedactURL for values that may be a remote name or a local
// path rather than a URL. See gitremote.RedactURLOrPath.
func RedactURLOrPath(target string) string {
	return gitremote.RedactURLOrPath(target)
}

func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
	logAttrs := []any{
		slog.String("operation", operation),
		slog.String("fallback_url", RedactURL(fallbackURL)),
		slog.String("reason", reason),
		slog.String("error", err.Error()),
	}
	logAttrs = append(logAttrs, attrs...)
	logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
}

func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
	if originURL != "" {
		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
				return tokenURL, nil
			}
		}
		return originURL, nil
	}
	if pushRemoteName == "" {
		return "", fmt.Errorf("no push remote specified and remote %q not found", originRemote)
	}
	if pushRemoteName == originRemote {
		return "", fmt.Errorf("remote %q not found", originRemote)
	}
	pushURL, err := GetRemoteURL(ctx, pushRemoteName)
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
		if tokenURL, ok := deriveTokenOriginURL(pushURL); ok {
			return tokenURL, nil
		}
	}
	return pushURL, nil
}

	if err := strategy.FetchMetadataBranch(ctx, checkpointURL); err != nil {
		return fmt.Errorf("failed to fetch from checkpoint remote: %w", err)
	}
	return nil
}

// resolveCheckpointFetchTarget returns the fetch target for checkpoint data.
// Thin alias for remote.CheckpointFetchTarget (the single source of truth).
func resolveCheckpointFetchTarget(ctx context.Context) string {
	return remote.CheckpointFetchTarget(ctx)
}

// FetchCheckpointRef fetches a single per-checkpoint ref from the ordered
// checkpoint read candidates. This is the CLI-side RefFetchFunc wiring point;
// write-hook probes use remote.HookCheckpointRefFetcher directly and remain
// confined to their selected target.
func FetchCheckpointRef(ctx context.Context, ref plumbing.ReferenceName) error {
	return remote.FetchCheckpointRefFrom(ctx, ref, strategy.CheckpointReadRemotes(ctx)) //nolint:wrapcheck // thin alias; the remote error carries full context
}

// checkpointRefListTimeout bounds the names-only ls-remote used by user-facing
// `entire checkpoint list` / branch explain. Kept short (not a full fetch
// budget): discovery is best-effort and additive — on timeout or unreachable
// remote the store falls back to local refs rather than stalling a previously
// instant command for tens of seconds.
const checkpointRefListTimeout = 5 * time.Second

// ListCheckpointRefsOnRemote enumerates the per-checkpoint refs
// (refs/entire/checkpoints/<shard>/<id>) present on the checkpoint remote(s),
// names only, via `git ls-remote refs/entire/checkpoints/*` — no object
// transfer. The git-refs store's List uses it to discover checkpoints written
// on another machine that have no local ref yet, then hydrates each lazily on
// read through FetchCheckpointRef.
//
// Scope:
//   - checkpoint_remote configured → queries the resolved dedicated URL via
//     remote.FetchURL (which can still fall through to origin in edge cases
//     such as settings-load failure or an underivable checkpoint URL) —
//     unchanged single-target behavior;
//   - otherwise → queries EVERY checkpoint read candidate (elected sync
//     remote, then the legacy origin tier) and MERGES the listings — a union
//     deduped by ref name. Merging rather than first-non-empty because
//     per-checkpoint refs land on whichever remote the pre-push hook fires
//     for, so disjoint legacy refs on origin coexisting with new refs on the
//     elected remote are realistic and first-non-empty would shadow one side.
//     Discovery is best-effort: a candidate failing logs at debug and doesn't
//     block the others, and when every candidate fails the result is
//     (nil, nil) so List stays local-only. No candidates (remoteless repo) →
//     (nil, nil).
//
// The single checkpointRefListTimeout budget spans the whole union.
// Resolution and ls-remote are pinned to the worktree root (not process cwd) so
// repo-local git config (url.*.insteadOf, credential helpers, remotes) applies.
func ListCheckpointRefsOnRemote(ctx context.Context) ([]plumbing.ReferenceName, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}

	s, settingsErr := settings.Load(settings.WithWorktreeRoot(ctx, worktreeRoot))
	if settingsErr != nil {
		logging.Warn(ctx, "checkpoint ref discovery: settings unavailable; leaving list local-only",
			slog.String("error", settingsErr.Error()))
		return nil, nil
	}
	if s.GetCheckpointRemote() != nil {
		url, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: worktreeRoot})
		if err != nil {
			return nil, fmt.Errorf("resolve checkpoint remote URL: %w", err)
		}

		ctx, cancel := context.WithTimeout(ctx, checkpointRefListTimeout)
		defer cancel()

		output, err := remote.LsRemoteInDir(ctx, worktreeRoot, url, checkpoint.CheckpointRefPrefix+"*")
		if err != nil {
			return nil, fmt.Errorf("ls-remote checkpoint refs from %s: %w", remote.RedactURL(url), err)
		}
		return parseCheckpointRefNames(output), nil
	}
	if s.HasCheckpointRemoteKey() {
		return nil, nil
	}

	candidates := strategy.CheckpointReadRemotes(ctx)
	if len(candidates) == 0 {
		return nil, nil
	}

	ctx, cancel := context.WithTimeout(ctx, checkpointRefListTimeout)
	defer cancel()

	seen := make(map[plumbing.ReferenceName]bool)
	var names []plumbing.ReferenceName
	for _, candidate := range candidates {
		// Prefer the candidate's resolved URL (token-aware, worktree-pinned);
		// fall back to the bare remote name, which git resolves itself.
		target := candidate
		if url, urlErr := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: worktreeRoot, LeadReadRemote: candidate}); urlErr == nil {
			target = url
		}
		output, lsErr := remote.LsRemoteInDir(ctx, worktreeRoot, target, checkpoint.CheckpointRefPrefix+"*")
		if lsErr != nil {
			logging.Debug(ctx, "checkpoint ref discovery: read candidate listing failed; continuing with remaining candidates",
				slog.String("candidate", candidate),
				slog.String("error", lsErr.Error()))
			continue
		}
		for _, name := range parseCheckpointRefNames(output) {
			if seen[name] {
				continue
			}
			seen[name] = true
			names = append(names, name)
		}
	}
	return names, nil
}

// parseCheckpointRefNames extracts the checkpoint ref names from `git ls-remote`
// output. Each line is "<hash>\t<refname>"; only refs under CheckpointRefPrefix
// are kept (the store re-validates each via ParseRef). Checkpoint refs point at
// commits so no peeled (`^{}`) lines appear for them; refs/tags peeled lines
// lack the checkpoint prefix and drop out here; any anomalous
// refs/entire/checkpoints/...^{} name is rejected by ParseRef downstream (the
// "{}" shard never matches ShardFor).
